package vn.covie.reputation.persistence;
import jakarta.persistence.LockModeType; import java.time.Instant; import java.util.Optional; import java.util.UUID; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.data.jpa.repository.Lock; import org.springframework.data.jpa.repository.Modifying; import org.springframework.data.jpa.repository.Query; import org.springframework.data.repository.query.Param; import vn.covie.reputation.model.UserReputationStatsEntity;
public interface UserReputationStatsRepository extends JpaRepository<UserReputationStatsEntity, UUID> { @Modifying(flushAutomatically=true) @Query(value="insert into user_reputation_stats(user_id,updated_at) values (:userId,:now) on conflict (user_id) do nothing",nativeQuery=true) int ensureEmpty(@Param("userId") UUID userId,@Param("now") Instant now); @Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select s from UserReputationStatsEntity s where s.userId=:userId") Optional<UserReputationStatsEntity> findForUpdate(@Param("userId") UUID userId); }
